insert into admin_test_results select plan(29);
insert into public.municipalities(id,name,state) values ('d5000000-0000-0000-0000-000000000001','Admin Test','Pruebas'),('d5000000-0000-0000-0000-000000000002','Other Test','Pruebas');
insert into auth.users(id,aud,role,email,email_confirmed_at) select ('d5100000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','admin-test-'||i||'@example.test',now() from generate_series(1,5) i;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('d5200000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,('d5100000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,now(),now() from generate_series(1,5) i;
insert into public.profiles(id,municipality_id,first_name) select ('d5100000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,case when i=5 then 'd5000000-0000-0000-0000-000000000002'::uuid else 'd5000000-0000-0000-0000-000000000001'::uuid end,'Test' from generate_series(1,5) i;
insert into public.user_roles(user_id,municipality_id,role_id) select p.id,p.municipality_id,r.id from public.profiles p join public.roles r on r.code=case right(p.id::text,1) when '1' then 'MUNICIPAL_ADMIN' when '2' then 'CITIZEN' when '3' then 'OPERATOR' when '4' then 'VIEWER' when '5' then 'MUNICIPAL_ADMIN' end where p.id::text like 'd5100000-%';
insert into public.priorities(id,municipality_id,name,rank) values ('d5300000-0000-0000-0000-000000000001','d5000000-0000-0000-0000-000000000001','Media',2);
insert into public.categories(id,municipality_id,name,default_priority_id) values ('d5400000-0000-0000-0000-000000000001','d5000000-0000-0000-0000-000000000001','Test','d5300000-0000-0000-0000-000000000001');
insert into public.departments(id,municipality_id,name) values ('d5600000-0000-0000-0000-000000000001','d5000000-0000-0000-0000-000000000001','Pruebas'),('d5600000-0000-0000-0000-000000000002','d5000000-0000-0000-0000-000000000002','Otros');
insert into public.reports(id,municipality_id,citizen_id,category_id,priority_id,status_id,description,idempotency_key,is_pilot) values
('d5500000-0000-0000-0000-000000000001','d5000000-0000-0000-0000-000000000001','d5100000-0000-0000-0000-000000000002','d5400000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000001',(select id from public.report_statuses where code='RECIBIDO'),'Reporte ficticio de prueba',gen_random_uuid(),true),
('d5500000-0000-0000-0000-000000000002','d5000000-0000-0000-0000-000000000001','d5100000-0000-0000-0000-000000000002','d5400000-0000-0000-0000-000000000001','d5300000-0000-0000-0000-000000000001',(select id from public.report_statuses where code='RECIBIDO'),'Reporte excluido no piloto',gen_random_uuid(),false);
