begin;
set local search_path=public,extensions;
create extension if not exists pgtap with schema extensions;
create temp table admin_test_results(result text);
grant all on admin_test_results to authenticated,anon;
create function pg_temp.claim(i integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d5100000-0000-0000-0000-'||lpad(i::text,12,'0'),'session_id','d5200000-0000-0000-0000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true); end;$$;
create function pg_temp.act(action text,data jsonb default '{}') returns jsonb language sql as $$select public.admin_pilot(action,'{"id":"d5500000-0000-0000-0000-000000000001"}'::jsonb||data)$$;
set local role anon;
set local role authenticated;
select pg_temp.claim(2);
select pg_temp.claim(3);
select pg_temp.claim(5);
select pg_temp.claim(1);
select pg_temp.claim(3);
select pg_temp.claim(4);
select pg_temp.claim(1);
reset role;
delete from auth.sessions where id='d5200000-0000-0000-0000-000000000001';
set local role authenticated;
reset role;
select jsonb_agg(result) as test_results from admin_test_results;
rollback;
